<?php
defined( 'ABSPATH' ) || exit;
$filters = array( 'activo' => 'Stock activo', 'disponible' => 'Disponibles', 'reservado' => 'Reservados', 'vendido' => 'Vendidos', 'borradores' => 'Borradores' );
$filter = is_string( $_GET['filtro'] ?? null ) && isset( $filters[ $_GET['filtro'] ] ) ? $_GET['filtro'] : 'activo';
$search = is_string( $_GET['buscar'] ?? null ) ? sanitize_text_field( wp_unslash( $_GET['buscar'] ) ) : '';
$page = is_string( $_GET['pagina'] ?? null ) && ctype_digit( $_GET['pagina'] ) ? max( 1, (int) $_GET['pagina'] ) : 1;
$result = rp_usados_gestion_list( array( 'filtro' => $filter, 'buscar' => $search, 'pagina' => $page ) );
if ( is_wp_error( $result ) ) { echo '<p role="alert">' . esc_html( $result->get_error_message() ) . '</p>'; return; }
?>
<div class="page-heading"><div><h1>Gestión de stock</h1><p>Vehículos, fotos y estado de publicación.</p></div><a class="button button-primary" href="<?php echo esc_url( home_url( '/gestion/nuevo/' ) ); ?>">+ Cargar vehículo</a></div>
<nav class="filters" aria-label="Filtrar vehículos"><?php foreach ( $filters as $key => $label ) : ?><a <?php if ( $filter === $key ) { echo 'aria-current="page"'; } ?> href="<?php echo esc_url( add_query_arg( array( 'filtro' => $key, 'buscar' => $search ), home_url( '/gestion/' ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?></nav>
<form method="get" class="search"><input type="hidden" name="filtro" value="<?php echo esc_attr( $filter ); ?>"><label for="buscar">Marca / Modelo / Versión</label><div class="search-controls"><input id="buscar" name="buscar" type="search" value="<?php echo esc_attr( $search ); ?>" maxlength="160"><button class="button" type="submit">Buscar</button><?php if ( $search ) : ?><a class="button" href="<?php echo esc_url( add_query_arg( 'filtro', $filter, home_url( '/gestion/' ) ) ); ?>">Limpiar</a><?php endif; ?></div></form>
<div class="list-caption"><h2><?php echo esc_html( $filters[ $filter ] ); ?></h2><span><?php echo esc_html( $result['total'] ); ?> vehículos</span></div>
<div id="list-feedback" class="feedback" role="status" aria-live="polite"></div>
<?php if ( ! $result['items'] ) : ?><section class="empty"><h2>No hay vehículos para mostrar</h2><p><?php echo $search ? 'Probá con otra búsqueda o quitá los filtros.' : 'Cargá un vehículo o revisá otro estado del stock.'; ?></p><a class="button" href="<?php echo esc_url( home_url( '/gestion/nuevo/' ) ); ?>">Cargar vehículo</a></section><?php endif; ?>
<div class="stock-list"><div class="stock-columns" aria-hidden="true"><span>Vehículo</span><span>Año</span><span>Kilometraje</span><span>Precio</span><span>Estado</span><span>Acciones</span></div>
<?php foreach ( $result['items'] as $v ) : ?>
<article class="stock-row" data-id="<?php echo esc_attr( $v['id'] ); ?>" data-revision="<?php echo esc_attr( $v['revision'] ); ?>" data-state="<?php echo esc_attr( $v['estado'] ); ?>">
<div class="vehicle-summary"><?php $photo = $v['portada'] ? wp_get_attachment_image_url( $v['portada'], 'thumbnail' ) : ''; if ( $photo ) : ?><img class="thumbnail" src="<?php echo esc_url( $photo ); ?>" alt="" width="88" height="66"><?php else : ?><div class="thumbnail no-photo">Sin foto</div><?php endif; ?>
<div><h3><?php echo esc_html( trim( $v['marca'] . ' ' . $v['modelo'] ) ?: 'Vehículo en borrador' ); ?></h3><p><?php echo esc_html( $v['version'] ?: 'Sin versión cargada' ); ?><span class="mobile-year"> · <?php echo esc_html( $v['anio'] ?: 'Sin año' ); ?></span></p></div></div>
<div class="row-year numeric"><span class="mobile-label">Año</span><?php echo esc_html( $v['anio'] ?: 'Sin año' ); ?></div>
<div class="numeric row-km"><span class="mobile-label">Kilometraje</span><?php echo esc_html( '' !== $v['kilometraje'] ? number_format( (int) $v['kilometraje'], 0, ',', '.' ) . ' km' : 'Sin kilometraje' ); ?></div>
<div class="numeric row-price"><span class="mobile-label">Precio</span><?php echo esc_html( rp_usados_gestion_format_price( $v ) ); ?></div>
<div class="row-state"><span class="mobile-label">Estado</span><span class="state-label"><?php echo esc_html( rp_usados_stock_labels()[ $v['estado'] ] ?? 'Sin estado' ); ?></span><?php if ( 'draft' === $v['publicacion'] ) : ?><small>Borrador</small><?php endif; ?></div>
<div class="row-actions"><a class="button" href="<?php echo esc_url( $v['editar_url'] ); ?>">Editar</a><details class="quick-state"><summary class="button">Cambiar estado</summary><form method="post" action="<?php echo esc_url( $v['editar_url'] ); ?>" class="state-form"><input type="hidden" name="accion" value="save"><?php wp_nonce_field( 'rp_gestion_save', '_rp_nonce', false ); ?><input type="hidden" name="rp_vehicle[revision]" value="<?php echo esc_attr( $v['revision'] ); ?>"><input type="hidden" name="guardar" value="changes"><label>Estado comercial<select name="rp_vehicle[estado]"><?php foreach ( rp_usados_stock_labels() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $v['estado'], $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></label><label class="checkbox"><input type="checkbox" name="confirmar_vendido" value="1"> Confirmo si pasa a vendido: dejará de aparecer en el catálogo. No se eliminará.</label><button class="button" type="submit">Guardar estado</button></form></details></div>
</article><?php endforeach; ?></div>
<?php if ( $result['paginas'] > 1 ) : ?><nav class="pagination" aria-label="Páginas de stock"><?php for ( $p = 1; $p <= $result['paginas']; $p++ ) : ?><a class="button" <?php if ( $p === $page ) { echo 'aria-current="page"'; } ?> href="<?php echo esc_url( add_query_arg( array( 'filtro' => $filter, 'buscar' => $search, 'pagina' => $p ), home_url( '/gestion/' ) ) ); ?>"><?php echo esc_html( $p ); ?></a><?php endfor; ?></nav><?php endif; ?>
